-- infra/postgres/init/01-schema.sql já cria "movimento_estoque" ao inicializar o volume;
-- os comandos abaixo são idempotentes para funcionar com ou sem esse script.
CREATE TABLE IF NOT EXISTS "movimento_estoque" (
	"movimento_id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "movimento_estoque_movimento_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"item_id" bigint NOT NULL,
	"tipo" varchar(20) NOT NULL,
	"quantidade" numeric(10, 2) NOT NULL,
	"data_hora" timestamp DEFAULT now() NOT NULL,
	"usuario_id" bigint,
	"os_id" bigint,
	"observacao" text,
	CONSTRAINT "movimento_estoque_tipo_check" CHECK ("movimento_estoque"."tipo" IN ('ENTRADA', 'SAIDA', 'AJUSTE')),
	CONSTRAINT "movimento_estoque_quantidade_check" CHECK ("movimento_estoque"."quantidade" > 0)
);
