DO $$
BEGIN
	IF NOT EXISTS (
		SELECT 1 FROM pg_constraint
		WHERE conrelid = 'public.movimento_estoque'::regclass
			AND confrelid = 'public.peca_insumo'::regclass
			AND contype = 'f'
	) THEN
		ALTER TABLE "movimento_estoque" ADD CONSTRAINT "movimento_estoque_item_id_peca_insumo_item_id_fk" FOREIGN KEY ("item_id") REFERENCES "public"."peca_insumo"("item_id") ON DELETE no action ON UPDATE no action;
	END IF;
END $$;
